-- D-COM-03/05 confirmed 23 October 2026: new contracts only.
UPDATE saas_catalog_versions SET status = 'RETIRED', retired_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP WHERE code = 'C8-2026-10-23' AND status = 'ACTIVE';
INSERT INTO saas_catalog_versions (id, code, status, currency, vat_rate_bps, effective_at, created_at, updated_at)
SELECT 'saas_catalog_c9_v1', 'C9-2026-10-24', 'ACTIVE', currency, vat_rate_bps, TIMESTAMP '2026-10-24 00:00:00', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM saas_catalog_versions WHERE id = 'saas_catalog_c8_v1';
INSERT INTO saas_plans (id, catalog_version_id, code, name, monthly_price_cents, annual_price_cents, included_driver_seats, unlimited_driver_seats, max_driver_seats, included_admin_seats, max_admin_seats, included_dispatcher_seats, max_dispatcher_seats, included_monthly_orders, order_overage_unit_price_cents, included_features, created_at, updated_at)
SELECT replace(id, '_c8_', '_c9_'), 'saas_catalog_c9_v1', code, name, monthly_price_cents, annual_price_cents, CASE WHEN code = 'BUSINESS' THEN 20 ELSE included_driver_seats END, false, CASE WHEN code = 'BUSINESS' THEN 50 ELSE max_driver_seats END, included_admin_seats, max_admin_seats, included_dispatcher_seats, max_dispatcher_seats, included_monthly_orders, order_overage_unit_price_cents, included_features, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM saas_plans WHERE catalog_version_id = 'saas_catalog_c8_v1';
INSERT INTO saas_options (id, catalog_version_id, code, name, kind, feature_key, seat_role, monthly_price_cents, annual_price_cents, applicable_plans, created_at, updated_at)
SELECT replace(id, '_c8_', '_c9_'), 'saas_catalog_c9_v1', code, name, kind, feature_key, seat_role, monthly_price_cents, annual_price_cents, applicable_plans, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM saas_options WHERE catalog_version_id = 'saas_catalog_c8_v1';
